arguments.command:
cd /tmp/w; for v in 1 2 3 4; do case $v in
1) sed 's/^bmb.*/bmb     dat     >2667,  >5334/' b1.red > v.red;;
2) sed 's/^bmb.*/bmb     spl     #0,  <5334/' b1.red > v.red;;
3) sed 's/mov.i   bmb,    {1612/mov.i   #1,    <1612/' b1.red > v.red;;
4) sed 's/^bmb.*/bmb     dat     <5334,  <2667/;s/jmp     p1,     <2921/jmp     p1,     >2921/' b1.red > v.red;;
esac; echo $v; python3 /app/tools/spar.py v.red --rounds 300 | tail -n1; done
